import SFRPGItemBase from './base-item.mjs';

const { fields } = foundry.data;

export default class SFRPGItemFeat extends SFRPGItemBase {

    static LOCALIZATION_PREFIXES = [
        'SFRPG.Item.Base',
        'SFRPG.Item.Feat'
    ];

    static defineSchema() {
        const schema = super.defineSchema();

        // merge schema with templates
        foundry.utils.mergeObject(schema, {
            ...SFRPGItemBase.actionTemplate(),
            ...SFRPGItemBase.activatedEffectTemplate()
        });

        // Feat-specific properties
        foundry.utils.mergeObject(schema, {
            activationEvent: new fields.SchemaField({
                activationTurn: new fields.StringField({ // Ideally this and expiryTurn would use a Uuid field, but sometimes they're set to "parent"
                    initial: "parent",
                    blank: true,
                    required: true
                }),
                deactivatedAt: new fields.NumberField({
                    initial: 0,
                    nullable: true,
                    integer: true,
                    required: true
                }),
                endsOn: new fields.StringField({
                    initial: "onTurnStart",
                    choices: Object.keys(CONFIG.SFRPG.effectEndTypes),
                    required: true
                }),
                endTime: new fields.AnyField({ // Temporary fix; should be NumberField but Text and Permanent durations cause issues
                    initial: 0,
                    nullable: true,
                    required: true
                }),
                expiryTurn: new fields.StringField({
                    initial: "parent",
                    blank: true,
                    required: true
                }),
                startTime: new fields.NumberField({
                    initial: 0,
                    nullable: false,
                    integer: true,
                    required: true
                }),
                status: new fields.StringField({
                    initial: "",
                    blank: true,
                    nullable: true,
                    required: true
                })
            }, {required: false}),
            details: new fields.SchemaField({
                category: new fields.StringField({
                    initial: "feat",
                    choices: Object.keys(CONFIG.SFRPG.featureCategories),
                    blank: false,
                    required: true,
                    label: "SFRPG.Items.Feat.FeatureCategory"
                }),
                combat: new fields.BooleanField({
                    initial: false,
                    label: "SFRPG.Items.Feat.CombatFeat"
                }),
                specialAbilityType: new fields.StringField({
                    initial: "",
                    choices: Object.keys(CONFIG.SFRPG.specialAbilityTypes),
                    blank: true,
                    required: true,
                    label: "SFRPG.Items.Feat.SpecialAbilityType"
                })
            }),
            recharge: new fields.SchemaField({
                value: new fields.StringField({
                    initial: "",
                    blank: true,
                    required: true,
                    label: "SFRPG.Items.Feat.ActionRecharge"
                }),
                charged: new fields.BooleanField({
                    initial: false,
                    label: "SFRPG.Items.Feat.Charged"
                })
            }),
            requirements: new fields.StringField({
                initial: "",
                blank: true,
                required: true,
                label: "SFRPG.Items.Feat.Requirements"
            })
        });

        // Add fields needed to existing base item fields
        foundry.utils.mergeObject(schema.activation.fields, {
            macroAfterActivate: new fields.DocumentUUIDField({
                initial: null,
                nullable: true,
                label: "SFRPG.Items.Feat.FeatureMacroAfterActivate"
            }),
            macroAfterDeactivate: new fields.DocumentUUIDField({
                initial: null,
                nullable: true,
                label: "SFRPG.Items.Feat.FeatureMacroAfterDeactivate"
            })
        });

        // No initial value changes to templated fields

        return schema;
    }
}
